use super::*;
use serde::{Serialize,Deserialize};
#[derive(Clone,Serialize,Deserialize)] #[serde(default)]
pub(super) struct Settings {pub theme:usize,pub accent:[u8;3],pub local:bool,pub resolution:[u32;2],pub dock:[usize;3],pub cache_mib:u32}
impl Default for Settings {fn default()->Self{Self{theme:0,accent:[78,139,209],local:false,resolution:[640,360],dock:[0,1,2],cache_mib:128}}}
#[derive(Default)] pub(super) struct Master {pub settings:Settings,pub paused:bool,pub step:bool,pub loaded:bool,pub profiler:bool,pub game:bool,pub asset_target:String,pub curve_axis:usize,pub curve_drag:Option<usize>}
fn settings_path()->PathBuf{std::env::var_os("APPDATA").or_else(||std::env::var_os("HOME")).map(PathBuf::from).unwrap_or_else(std::env::temp_dir).join("ForgeEngine").join("master36.json")}
pub(super) fn init(e:&mut Editor){if e.master.loaded{return;}e.master.loaded=true;if let Ok(b)=std::fs::read(settings_path()){if let Ok(s)=serde_json::from_slice::<Settings>(&b){e.master.settings=s;}}e.master.settings.theme=e.master.settings.theme.min(2);for x in &mut e.master.settings.dock{*x=(*x).min(3);}for x in &mut e.master.settings.resolution{*x=(*x).clamp(64,3840);}}
pub(super) fn save(e:&mut Editor){let p=settings_path();let result=(||->Result<(),String>{std::fs::create_dir_all(p.parent().unwrap()).map_err(|x|x.to_string())?;std::fs::write(p,serde_json::to_vec_pretty(&e.master.settings).map_err(|x|x.to_string())?).map_err(|x|x.to_string())})();e.status=result.map(|_|"Workspace settings saved".into()).unwrap_or_else(|x|x);}
pub(super) fn theme(ctx:&egui::Context,e:&Editor){let s=&e.master.settings;let key=egui::Id::new("forge_theme_0711");let signature=(s.theme,s.accent);if ctx.data(|d|d.get_temp::<(usize,[u8;3])>(key))==Some(signature){return;}ctx.data_mut(|d|d.insert_temp(key,signature));let mut v=if s.theme==1{egui::Visuals::light()}else{egui::Visuals::dark()};if s.theme!=1{v.panel_fill=if s.theme==2{egui::Color32::BLACK}else{egui::Color32::from_rgb(28,32,40)};v.window_fill=if s.theme==2{egui::Color32::from_gray(12)}else{egui::Color32::from_rgb(35,40,49)};}v.selection.bg_fill=egui::Color32::from_rgb(s.accent[0],s.accent[1],s.accent[2]);ctx.set_visuals(v);ctx.style_mut(|s|{s.spacing.item_spacing=egui::vec2(5.,4.);s.spacing.button_padding=egui::vec2(6.,3.);});}
pub(super) fn menu(ui:&mut egui::Ui,e:&mut Editor){let uk=e.uk;for (i,n) in [tr(uk,"Темна","Dark"),tr(uk,"Світла","Light"),"OLED"].iter().enumerate(){ui.selectable_value(&mut e.master.settings.theme,i,*n);}ui.color_edit_button_srgb(&mut e.master.settings.accent);ui.add(egui::DragValue::new(&mut e.master.settings.cache_mib).range(32..=1024).suffix(" MiB").prefix("Viewport cache: "));ui.checkbox(&mut e.master.settings.local,tr(uk,"Локальні осі","Local axes"));ui.checkbox(&mut e.master.profiler,tr(uk,"Профайлер","Profiler"));ui.checkbox(&mut e.master.game,tr(uk,"Ігровий перегляд","Game preview"));for (i,n) in [tr(uk,"Сцена","Scene"),tr(uk,"Інспектор","Inspector"),tr(uk,"Інструменти","Tools")].iter().enumerate(){egui::ComboBox::from_id_salt(("dock36",i)).selected_text(["Left","Right","Bottom","Top"][e.master.settings.dock[i]]).show_ui(ui,|ui|{ui.label(*n);for (j,p) in ["Left","Right","Bottom","Top"].iter().enumerate(){ui.selectable_value(&mut e.master.settings.dock[i],j,*p);}});}if ui.button(tr(uk,"Зберегти","Save workspace")).clicked(){save(e);}}
pub(super) fn dock(ctx:&egui::Context,id:&str,zone:usize,default_size:f32,panel:impl FnOnce(&mut egui::Ui)){match zone{0=>{egui::SidePanel::left(id.to_owned()).resizable(true).default_width(default_size).show(ctx,panel);},1=>{egui::SidePanel::right(id.to_owned()).resizable(true).default_width(default_size).show(ctx,panel);},3=>{egui::TopBottomPanel::top(id.to_owned()).resizable(true).default_height(default_size).show(ctx,panel);},_=>{egui::TopBottomPanel::bottom(id.to_owned()).resizable(true).default_height(default_size).show(ctx,panel);}}}
pub(super) fn preview(ctx:&egui::Context,e:&mut Editor,texture:egui::TextureId){if !e.master.game{return;}let mut open=true;egui::Window::new(tr(e.uk,"Ігровий перегляд","Game preview PRO")).open(&mut open).default_width(520.).show(ctx,|ui|{ui.horizontal(|ui|{if ui.button(if e.play.is_some(){"Stop"}else{"Play"}).clicked(){if e.play.is_some(){e.play=None;}else{e.sim=Simulation::default();e.play=Some(e.project.clone());}e.master.paused=false;}if ui.button(if e.master.paused{"Resume"}else{"Pause"}).clicked(){e.master.paused=!e.master.paused;}if ui.button("Step 1/60").clicked(){e.master.paused=true;e.master.step=true;}for x in &mut e.master.settings.resolution{ui.add(egui::DragValue::new(x).range(64..=3840));}});let [w,h]=e.master.settings.resolution;let width=ui.available_width().max(32.);if e.project.objects.iter().any(|o|o.camera){ui.image((texture,egui::vec2(width,width*h as f32/w as f32)));}else{ui.label(tr(e.uk,"Додайте Camera2D","Add Camera2D"));}});e.master.game=open;}
pub(super) fn profiler(ctx:&egui::Context,e:&mut Editor){if !e.master.profiler{return;}let mut open=true;egui::Window::new("Performance profiler").open(&mut open).show(ctx,|ui|{let p=e.play.as_ref().unwrap_or(&e.project);ui.label(format!("FPS {:.1} | frame {:.2} ms",e.pro.fps,1000./e.pro.fps.max(1.)));ui.label(format!("Objects: {} | sprites: {}",p.objects.len(),p.objects.iter().filter(|o|o.sprite.is_some()).count()));let bytes:usize=e.textures.values().map(|t|{let [w,h]=t.size();w.saturating_mul(h).saturating_mul(4)}).sum();ui.label(format!("egui texture estimate: {:.2} MiB",bytes as f64/1048576.));let (used,hits,misses,evictions)=super::viewport::cache_stats();ui.label(format!("Viewport cache {:.1} MiB | hits {hits} | misses {misses} | evictions {evictions}",used as f64/1048576.));ui.label("Not total process or GPU memory");});e.master.profiler=open;}
pub(super) fn axes(rotation:f32,local:bool)->[egui::Vec2;2]{let a=if local{rotation.to_radians()}else{0.};let(s,c)=a.sin_cos();[egui::vec2(c,-s),egui::vec2(-s,-c)]}
pub(super) fn curve(ui:&mut egui::Ui,o:&mut Object,m:&mut Master,time:&mut f32){ui.horizontal(|ui|{for (i,n) in ["X","Y","Rotation"].iter().enumerate(){ui.selectable_value(&mut m.curve_axis,i,*n);}});let axis=m.curve_axis.min(2);let value=|k:&forge_engine::Key|if axis==2{k.rotation}else{k.position[axis]};let end=o.motion.keys.iter().map(|k|k.time).fold(2.,f32::max)*1.2;let scale=o.motion.keys.iter().map(|k|value(k).abs()).fold(10.,f32::max)*1.3;let(r,response)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(80.),130.),egui::Sense::click_and_drag());let p=ui.painter_at(r);let point=|t:f32,v:f32|egui::pos2(r.left()+t/end*r.width(),r.center().y-v/scale*r.height()*0.45);p.rect_filled(r,2.,ui.visuals().extreme_bg_color);p.line_segment([point(0.,0.),point(end,0.)],egui::Stroke::new(1.,egui::Color32::GRAY));let pts=(0..=128).filter_map(|i|{let t=end*i as f32/128.;o.motion.sample(t).map(|(v,a)|point(t,if axis==2{a}else{v[axis]}))}).collect::<Vec<_>>();if pts.len()>1{p.add(egui::Shape::line(pts,egui::Stroke::new(2.,egui::Color32::LIGHT_BLUE)));}for k in &o.motion.keys{p.circle_filled(point(k.time,value(k)),5.,egui::Color32::from_rgb(235,185,70));}if response.drag_started()||response.clicked(){if let Some(pos)=response.interact_pointer_pos(){m.curve_drag=o.motion.keys.iter().enumerate().filter(|(_,k)|point(k.time,value(k)).distance(pos)<12.).min_by(|(_,a),(_,b)|point(a.time,value(a)).distance(pos).total_cmp(&point(b.time,value(b)).distance(pos))).map(|(i,_)|i);}}if response.dragged(){if let Some((i,pos))=m.curve_drag.zip(response.interact_pointer_pos()){if let Some(k)=o.motion.keys.get_mut(i){k.time=((pos.x-r.left())/r.width()*end).clamp(0.,3600.);let v=(r.center().y-pos.y)/r.height()/0.45*scale;if axis==2{k.rotation=v;}else{k.position[axis]=v;}*time=k.time;}}}if response.drag_stopped(){m.curve_drag=None;}if let Some(k)=o.motion.keys.iter_mut().min_by(|a,b|(a.time-*time).abs().total_cmp(&(b.time-*time).abs())){ui.checkbox(&mut k.smooth,"Smooth cubic interpolation");let mut enabled=k.bezier.is_some();if ui.checkbox(&mut enabled,"Bezier controls").changed(){k.bezier=enabled.then_some([[0.33,0.67];3]);}if let Some(handles)=&mut k.bezier{let pair=&mut handles[axis];let (r,response)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(100.),85.),egui::Sense::click_and_drag());let p=ui.painter_at(r);let point=|t:f32,v:f32|egui::pos2(r.left()+t*r.width(),r.bottom()-v*r.height());let a=point(0.,0.);let b=point(1./3.,pair[0]);let c=point(2./3.,pair[1]);let d=point(1.,1.);p.line_segment([a,b],egui::Stroke::new(1.,egui::Color32::GRAY));p.line_segment([c,d],egui::Stroke::new(1.,egui::Color32::GRAY));p.add(egui::Shape::line((0..=64).map(|i|{let t=i as f32/64.;let v=1.-t;point(t,3.*v*v*t*pair[0]+3.*v*t*t*pair[1]+t*t*t)}).collect(),egui::Stroke::new(2.,egui::Color32::LIGHT_BLUE)));for q in [b,c]{p.circle_filled(q,5.,egui::Color32::GOLD);}if response.dragged()||response.clicked(){if let Some(pos)=response.interact_pointer_pos(){let i=if pos.x<r.center().x{0}else{1};pair[i]=((r.bottom()-pos.y)/r.height()).clamp(0.,1.);}}}}}
pub(super) fn asset_tools(ui:&mut egui::Ui,e:&mut Editor){let uk=e.uk;ui.horizontal_wrapped(|ui|{if ui.button(tr(uk,"Імпорт папки","Import folder")).clicked(){if let Some(root)=e.path.as_ref().and_then(|p|p.parent()).map(|p|p.to_path_buf()){if let Some(src)=rfd::FileDialog::new().pick_folder(){e.status=forge_engine::import_folder(&src,&root).map(|n|format!("Imported {n} images")).unwrap_or_else(|x|x);e.pro.last_scan=None;}}else{e.status="Save project first".into();}}if let Some(old)=e.pro.asset_pick.clone(){ui.label(format!("{} refs",e.project.objects.iter().filter(|o|o.sprite.as_ref()==Some(&old)).count()));ui.text_edit_singleline(&mut e.master.asset_target);if ui.button(tr(uk,"Перемістити / перейменувати","Move / rename")).clicked(){if let Some(root)=e.path.as_ref().and_then(|p|p.parent()){if e.ultimate.documents.len()>1||!e.undo.is_empty()||!e.redo.is_empty()||e.saved!=e.project{e.status="Save and reopen project with a single tab before moving assets (history safety)".into();}else{let new=e.master.asset_target.clone();match forge_engine::move_asset(root,&mut e.project,&old,&new){Ok(())=>{e.pro.asset_pick=Some(new);e.pro.last_scan=None;e.textures.clear();e.stamps.clear();e.status="Asset moved; save project now".into();},Err(x)=>e.status=x}}}}}});}
